package com.examservice.presentation.controller;import com.examservice.application.service.*;import com.examservice.domain.model.ExamMatrixRule;import com.examservice.presentation.request.ExamRequests.*;import com.examservice.presentation.response.*;import com.examservice.presentation.response.ExamViews.*;import com.examservice.presentation.support.ActorResolver;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")public class ExamController{private final MatrixService matrices;private final TemplateService templates;private final ExamGenerationService exams;private final ActorResolver actors;public ExamController(MatrixService m,TemplateService t,ExamGenerationService e,ActorResolver a){matrices=m;templates=t;exams=e;actors=a;}
@PostMapping("/exam-matrices")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<MatrixView>createMatrix(@AuthenticationPrincipal Jwt j,@Valid@RequestBody MatrixRequest r){return ApiResponse.ok(MatrixView.from(matrices.save(null,r.name(),r.facultyId(),r.subjectId(),r.totalQuestions(),rules(r),actors.from(j))));}@PutMapping("/exam-matrices/{id}")public ApiResponse<MatrixView>updateMatrix(@PathVariable UUID id,@AuthenticationPrincipal Jwt j,@Valid@RequestBody MatrixRequest r){return ApiResponse.ok(MatrixView.from(matrices.save(id,r.name(),r.facultyId(),r.subjectId(),r.totalQuestions(),rules(r),actors.from(j))));}@GetMapping("/exam-matrices/{id}")public ApiResponse<MatrixView>getMatrix(@PathVariable UUID id,@AuthenticationPrincipal Jwt j){return ApiResponse.ok(MatrixView.from(matrices.get(id,actors.from(j))));}@GetMapping("/exam-matrices")public ApiResponse<List<MatrixView>>listMatrices(@AuthenticationPrincipal Jwt j){return ApiResponse.ok(matrices.list(actors.from(j)).stream().map(MatrixView::from).toList());}@PostMapping("/exam-matrices/{id}/validate")public ApiResponse<Boolean>validate(@PathVariable UUID id,@AuthenticationPrincipal Jwt j){matrices.validate(id,actors.from(j));return ApiResponse.ok(true);}
@PostMapping("/exam-templates")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<TemplateView>createTemplate(@AuthenticationPrincipal Jwt j,@Valid@RequestBody TemplateRequest r){return ApiResponse.ok(TemplateView.from(templates.create(r.name(),r.matrixId(),r.header(),r.instructions(),actors.from(j))));}@GetMapping("/exam-templates/{id}")public ApiResponse<TemplateView>getTemplate(@PathVariable UUID id,@AuthenticationPrincipal Jwt j){return ApiResponse.ok(TemplateView.from(templates.get(id,actors.from(j))));}
@PostMapping("/exams/generate")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<ExamView>generate(@AuthenticationPrincipal Jwt j,@Valid@RequestBody GenerateRequest r){return ApiResponse.ok(ExamView.from(exams.generate(r.name(),r.matrixId(),r.templateId(),actors.from(j))));}@GetMapping("/exams")public ApiResponse<List<ExamView>>listExams(@AuthenticationPrincipal Jwt j){return ApiResponse.ok(exams.list(actors.from(j)).stream().map(ExamView::from).toList());}@GetMapping("/exams/{id}")public ApiResponse<ExamView>getExam(@PathVariable UUID id,@AuthenticationPrincipal Jwt j){return ApiResponse.ok(ExamView.from(exams.get(id,actors.from(j))));}@PostMapping("/exams/{id}/versions")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<ExamView>regenerate(@PathVariable UUID id,@AuthenticationPrincipal Jwt j){return ApiResponse.ok(ExamView.from(exams.regenerate(id,actors.from(j))));}
private List<ExamMatrixRule>rules(MatrixRequest r){return r.rules().stream().map(x->new ExamMatrixRule(UUID.randomUUID(),x.chapterId(),x.topicId(),x.difficulty(),x.questionCount())).toList();}}
